import pathlib,json,base64
root=pathlib.Path('build/offline/assets');assets={}
for p in root.rglob('*'):
 if not p.is_file():continue
 key='/gameData/'+('ids.json' if p.name=='ids.json' else 'data/'+p.relative_to(root).as_posix())
 if p.suffix=='.json':assets[key]=json.loads(p.read_text())
 else:assets[key]='data:'+('audio/mpeg' if p.suffix=='.mp3' else 'image/png')+';base64,'+base64.b64encode(p.read_bytes()).decode()
assets['/settings/controls.json']=json.loads(pathlib.Path('nova/settings/controls.json').read_text())
assets['defaultPict']='data:image/png;base64,'+base64.b64encode(pathlib.Path('novadatainterface/default_pict.png').read_bytes()).decode()
html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,user-scalable=no"><title>NovaJS — Offline single player</title><style>html,body{margin:0;background:#000;color:#b9dbed;overflow:hidden;font:16px system-ui}#loading{position:fixed;inset:0;z-index:999;background:#08111c;display:grid;place-content:center;text-align:center}#error{position:fixed;top:0;left:0;background:#401919;color:white;z-index:9999;max-height:40vh;overflow:auto}#touch{position:fixed;bottom:8px;left:8px;right:8px;display:flex;justify-content:space-between;pointer-events:none;z-index:20}button{pointer-events:auto;touch-action:none;background:#15283bcc;color:#d6eaff;border:1px solid #537087;border-radius:8px;padding:13px;margin:2px;font:16px system-ui;user-select:none}#help{position:fixed;top:8px;right:8px;z-index:20}dialog{background:#102030;color:#e0efff;max-width:440px;border:1px solid #6383a3}a{color:#9bceff}</style></head><body><div id="loading"><h1>NovaJS</h1><p>Loading your EV Nova data…</p></div><pre id="error" hidden></pre><button id="help" onclick="document.getElementById('about').showModal()">?</button><dialog id="about"><h2>NovaJS offline</h2><p>Adapted from Matthew Soulanille and contributors’ NovaJS engine. Uses the game data you supplied. This is the experimental NovaJS engine, not a complete port of the original campaign.</p><p>Arrows: fly · Space: fire · L: land · M: map · J: jump · Tab: target · W: secondary weapon · Shift: fire secondary · Escape: depart/close.</p><p>Mobile buttons provide the main flight controls. Landscape recommended. No multiplayer or persistent pilot save is included.</p><a href="https://github.com/mattsoulanille/NovaJS">Original project</a><p><button onclick="this.closest('dialog').close()">Return</button></p><details><summary>Engine license</summary><pre style="white-space:pre-wrap">'''+pathlib.Path('LICENSE').read_text()+'''</pre></details></dialog><div id="touch"><div><button data-key="ArrowLeft">↶</button><button data-key="ArrowUp">▲</button><button data-key="ArrowRight">↷</button><button data-key="ArrowDown">▼</button></div><div><button data-key="KeyM">Map</button><button data-key="KeyJ">Jump</button><button data-key="KeyL">Land</button><button data-key="Escape">Back</button><button data-key="Tab">Target</button><button data-key="Space">Fire</button></div></div><script>window.showError=e=>{console.error(e);const el=document.getElementById('error');el.hidden=false;el.textContent+=String(e?.stack||e)+'\\n';};window.addEventListener('error',e=>showError(e.error||e.message));window.addEventListener('unhandledrejection',e=>showError(e.reason));for(const b of document.querySelectorAll('[data-key]')){const send=t=>document.dispatchEvent(new KeyboardEvent(t,{key:b.dataset.key==='Space'?' ':b.dataset.key,code:b.dataset.key,bubbles:true}));b.onpointerdown=e=>{e.preventDefault();try{b.setPointerCapture(e.pointerId)}catch{}send('keydown')};b.onpointerup=b.onpointercancel=()=>send('keyup');}window.novaAssets='''
html+=json.dumps(assets,separators=(',',':')).replace('</','<\\/')+';</script><script>'+pathlib.Path('build/offline/browser.js').read_text().replace('</script','<\\/script')+'</script></body></html>'
pathlib.Path('build/offline/NovaJS-Offline.html').write_text(html)
print('HTML MB',len(html)/1e6)
